script:
(() => {
  const $ = id => document.getElementById(id);
  const api = (action, params = {}) => tinyassets.call(action, params);
  const views = ['Chat', 'Feed', 'Ideas', 'Goals', 'Files'];
  let view = 'Chat', generation = 0, directory = '';
  const say = (text, error = false) => { $('status').textContent = text; $('status').dataset.error = String(error); };
  function element(tag, text, parent) {
    const el = document.createElement(tag); el.textContent = text;
    if (parent) parent.append(el); return el;
  }
  function button(text, action, parent) {
    const el = element('button', text, parent); el.type = 'button';
    el.onclick = () => Promise.resolve().then(action).catch(e => say(e.message, true));
    return el;
  }
  async function file(path) {
    let offset = 0, text = '';
    while (true) {
      const chunk = await api('read_file', {path, offset});
      if (chunk.encoding !== 'text') throw new Error('This is a media or binary file. Ask your agent to open or deliver it.');
      text += chunk.content;
      if (chunk.next_offset === null || chunk.next_offset === undefined) return text;
      if (chunk.next_offset <= offset) throw new Error('File pagination did not advance.');
      offset = chunk.next_offset;
    }
  }
  async function render() {
    const token = ++generation, selected = view;
    const host = document.createElement('div');
    $('composer').hidden = selected !== 'Chat';
    document.querySelectorAll('nav button').forEach(b => b.setAttribute('aria-current', b.textContent === selected ? 'page' : 'false'));
    say('Loading...');
    try {
      if (selected === 'Chat') {
        const data = await api('read_conversation', {limit: 30});
        if (!data.turns.length) element('p', 'What would you like to work on?', host);
        for (const turn of [...data.turns].reverse()) element('article', turn.speaker + ': ' + turn.text + (turn.truncated ? '\n[Message shortened; open the full chat to read more.]' : ''), host);
        if (data.has_more) button('Open full chat', () => api('open_chat', {agent: 'main'}), host);
      } else if (selected === 'Feed') {
        element('pre', await file('starter/feed.md'), host);
      } else if (selected === 'Ideas') {
        const ideas = JSON.parse(await file('starter/ideas.json'));
        if (!Array.isArray(ideas) || ideas.some(i => typeof i !== 'string')) throw new Error('ideas.json must be a list of prompts.');
        for (const idea of ideas) button(idea, async () => { view = 'Chat'; await render(); $('message').value = idea; $('message').focus(); }, host);
      } else if (selected === 'Goals') {
        const data = JSON.parse(await file('starter/goals.json'));
        if (!Array.isArray(data.goals)) throw new Error('goals.json must contain a goals list.');
        if (!data.goals.length) element('p', 'Tell your agent about a goal you want to work toward.', host);
        for (const goal of data.goals) {
          const card = element('article', '', host);
          element('h2', goal.title, card);
          element('p', goal.status + (goal.due ? ' - Due ' + goal.due : ''), card);
          element('p', goal.next_step || 'No next step yet.', card);
        }
      } else {
        const listing = await api('list_files', {path: directory});
        element('h2', directory || 'Your files', host);
        if (directory) button('Up one folder', () => { directory = directory.split('/').slice(0, -1).join('/'); return render(); }, host);
        for (const entry of listing.entries) {
          const path = [directory, entry.name].filter(Boolean).join('/');
          button(entry.name + (entry.kind === 'dir' ? '/' : ''), async () => {
            if (entry.kind === 'dir') { directory = path; return render(); }
            const text = await file(path);
            if (token === generation) { host.querySelector('pre')?.remove(); element('pre', text, host); }
          }, host);
        }
        if (listing.truncated) element('p', 'This folder listing is incomplete. Ask your agent to inspect it.', host);
      }
      if (token !== generation) return;
      $('content').replaceChildren(host); say('');
    } catch (e) {
      if (token === generation) { $('content').replaceChildren(); say(e.message, true); }
    }
  }
  for (const name of views) button(name, () => { view = name; return render(); }, document.querySelector('nav'));
  $('refresh').onclick = render;
  $('composer').onsubmit = async event => {
    event.preventDefault(); const text = $('message').value.trim(); if (!text) return;
    const submit = $('composer').querySelector('button'); submit.disabled = true;
    try { await api('send_message', {text}); $('message').value = ''; await render(); }
    catch (e) { say(e.message, true); } finally { submit.disabled = false; }
  };
  render();
})();
